export function ExecutiveCockpit() {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function initController() {
      if ((window as any).bootstrapCockpit) {
        (window as any).bootstrapCockpit();
        return;
      }

      const existingScript = document.getElementById("cockpit-controller-script");
      if (!existingScript) {
        const script = document.createElement("script");
        script.id = "cockpit-controller-script";
        script.src = "/assets/cockpit-controller.js";
        script.async = true;
        script.onload = () => {
          if ((window as any).bootstrapCockpit) {
            (window as any).bootstrapCockpit();
          }
        };
        document.body.appendChild(script);
      } else {
        if ((window as any).bootstrapCockpit) {
          (window as any).bootstrapCockpit();
        }
      }
    }

    const t = setTimeout(initController, 40);
    return () => clearTimeout(t);
  }, []);

  return (
    <div
      ref={containerRef}
      className="min-h-screen bg-[#020203] text-[#f4f4f5] antialiased selection:bg-white/20 pb-32"
      dangerouslySetInnerHTML={{ __html: COCKPIT_HTML }}
    />
  );
}
